105	    /**
106	     * Calculates the charge for a procedure. The procedure code is normalized with {@code trim()};
107	     * a {@code null} or blank code yields {@link BigDecimal#ZERO}.
108	     */
109	    public BigDecimal calculateCharge(String procedureCode, PricingContext context) {
110	        if (procedureCode == null || procedureCode.trim().isEmpty()) {
111	            log.warn("Empty procedure code provided");
112	            return BigDecimal.ZERO;
113	        }
114	        procedureCode = procedureCode.trim();
115	
116	        BigDecimal baseCharge = resolveBaseCharge(procedureCode);
117	
118	        if (baseCharge.compareTo(BigDecimal.ZERO) == 0) {
119	            log.warn("No pricing found for procedure: {}", procedureCode);
120	            return BigDecimal.ZERO;
121	        }
122	
123	        BigDecimal adjusted = applyAdjustments(procedureCode, baseCharge, context);
124	
125	        BigDecimal withDiscounts = applyDiscounts(procedureCode, adjusted, context);
126	
127	        BigDecimal withSurcharges = applySurcharges(procedureCode, withDiscounts, context);
128	
129	        BigDecimal withTax = applyTax(procedureCode, withSurcharges, context);
130	
131	        BigDecimal rounded = roundToNearestCent(withTax);
132	
133	        BigDecimal final_amount = applyLegacyScript(procedureCode, rounded, context);
134	
135	        log.debug("Calculated charge for {}: {} -> {} -> {} -> {} -> {} -> {}",
136	                procedureCode, baseCharge, adjusted, withDiscounts, withSurcharges, withTax, final_amount);
137	
138	        return final_amount;
139	    }
