414	        String family = resolveFamily(procedureCode);
415	
416	        BigDecimal taxRate = BigDecimal.ZERO;
417	
418	        switch (family) {
419	            case "OFFICE_VISIT_NEW":
420	            case "OFFICE_VISIT_ESTABLISHED":
421	            case "TELEHEALTH":
422	                taxRate = BigDecimal.ZERO;
423	                break;
424	            case "RADIOLOGY":
425	            case "LABORATORY":
426	                if (context.getState() != null) {
427	                    switch (context.getState()) {
428	                        case "CA":
429	                            taxRate = new BigDecimal("0.0725");
430	                            break;
431	                        case "TX":
432	                            taxRate = new BigDecimal("0.0625");
433	                            break;
434	                        case "NY":
435	                            taxRate = new BigDecimal("0.08");
436	                            break;
437	                        case "FL":
438	                            taxRate = new BigDecimal("0.06");
439	                            break;
440	                        default:
441	                            taxRate = new BigDecimal("0.05");
442	                    }
443	                } else {
444	                    taxRate = new BigDecimal("0.05");
445	                }
446	                break;
447	            case "PROCEDURE":
448	                taxRate = new BigDecimal("0.03");
449	                break;
450	            default:
451	                taxRate = new BigDecimal("0.05");
452	        }
453	
454	        if (Boolean.TRUE.equals(context.isTaxExempt())) {
455	            taxRate = BigDecimal.ZERO;
456	        }
457	
458	        BigDecimal taxAmount = amount.multiply(taxRate);
459	        return amount.add(taxAmount);
460	    }
