503	            return "LABORATORY";
504	        } else if (procedureCode.startsWith("TEL")) {
505	            return "TELEHEALTH";
506	        } else if (procedureCode.startsWith("PROC")) {
507	            return "PROCEDURE";
508	        }
509	        return "UNKNOWN";
510	    }
