512	    private boolean isHoliday(LocalDate date) {
513	        int month = date.getMonthValue();
514	        int day = date.getDayOfMonth();
515	
516	        if (month == 1 && day == 1) return true;
517	        if (month == 7 && day == 4) return true;
518	        if (month == 12 && day == 25) return true;
519	        if (month == 11 && day >= 22 && day <= 28 && date.getDayOfWeek() == DayOfWeek.THURSDAY) return true;
